 let lang='fr';const select=document.getElementById('admin-language');try{lang=localStorage.getItem('jorsid-language')||'de'}catch(e){}if(!['de','fr','en'].includes(lang))lang='de';if(select)select.value=lang;
 const nodes=[];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walker.nextNode())nodes.push(walker.currentNode);const originals=new WeakMap();nodes.forEach(n=>originals.set(n,n.nodeValue));
 function apply(l){lang=l;notificationLang=l;const i={de:0,fr:1,en:2}[l];document.documentElement.lang=l;document.querySelectorAll('button').forEach(b=>{if(!b.dataset.v6Label)b.dataset.v6Label=b.textContent.trim()});nodes.forEach(n=>{const raw=originals.get(n);const key=raw.trim();if(!key)return;const val=dictionary[key]?.[i];n.nodeValue=val!==undefined?raw.replace(key,val):raw});document.querySelectorAll('[placeholder]').forEach(el=>{if(!el.dataset.v6Placeholder)el.dataset.v6Placeholder=el.getAttribute('placeholder');const val=el.dataset.v6Placeholder;el.setAttribute('placeholder',dictionary[val]?.[i]||val)});document.querySelectorAll('button[title]').forEach(el=>{const val=el.dataset.v6Label||el.title;el.title=dictionary[val]?.[i]||val;el.setAttribute('aria-label',el.title)});document.querySelectorAll('button').forEach(b=>{if(!b.dataset.v6Label){b.dataset.v6Label=b.textContent.trim();b.title=b.dataset.v6Label;b.setAttribute('aria-label',b.dataset.v6Label)} });try{localStorage.setItem('jorsid-language',l)}catch(e){}}
 if(select)select.addEventListener('change',()=>apply(select.value));apply(lang);
})();
</script>
<script>
(()=>{
 const forms=[...document.querySelectorAll('.admin-v6 .main form')];let index=0;
 forms.forEach(form=>{
   if(!form.isConnected||form.classList.contains('no-auto-modal')||form.closest('dialog')||form.method.toLowerCase()==='get'||form.action.endsWith('/deconnexion'))return;
   if(form.matches('.row')||form.querySelector('.sr-only'))return;
   const controls=[...form.querySelectorAll('input:not([type=hidden]):not([type=submit]),select,textarea')];
   if(!controls.length)return;
   const submit=form.querySelector('button[type=submit],button:not([type]),input[type=submit]');
   const actionLabel=(submit?.textContent||submit?.value||'Enregistrer').trim().replace(/\s+/g,' ');
   const section=form.closest('.panel,section')||form.parentElement;
   const heading=section?.querySelector(':scope > h2, :scope > .row h2, :scope > div > h2');
   const title=(heading?.textContent||form.closest('details')?.querySelector('summary')?.textContent||actionLabel).trim().replace(/\s+/g,' ');
   const dialog=document.createElement('dialog');dialog.className='admin-generated-modal';dialog.setAttribute('aria-label',title);
   const header=document.createElement('div');header.className='modal-head';header.innerHTML=`<div><div class="muted" style="font-size:10px;font-weight:800;letter-spacing:.1em">JORSID BEAUTY · ADMINISTRATION</div><strong style="font-size:17px;color:#23495e">${title.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</strong></div><button type="button" class="modal-close" aria-label="Schließen">×</button>`;
   const body=document.createElement('div');body.className='modal-body';dialog.append(header,body);
   const trigger=document.createElement('button');trigger.type='button';trigger.className='admin-modal-trigger secondary';trigger.textContent=actionLabel==='Enregistrer'?'Formular öffnen':actionLabel;trigger.addEventListener('click',()=>dialog.showModal());
   form.replaceWith(trigger);body.appendChild(form);document.body.appendChild(dialog);
   const submitControl=form.querySelector('button[type="submit"],button:not([type]),input[type="submit"]');
   if(submitControl&&!form.querySelector('.form-actions')){const actions=document.createElement('div');actions.className='form-actions';const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='Annuler';cancel.addEventListener('click',()=>dialog.close());const parent=submitControl.parentElement;if(parent===form){form.appendChild(actions)}else{parent.appendChild(actions)}actions.append(cancel);actions.append(submitControl)}
   form.addEventListener('submit',()=>{if(submitControl){submitControl.disabled=true;submitControl.dataset.originalText=submitControl.textContent;submitControl.textContent=/supprim|delete/i.test(submitControl.textContent)?'Suppression…':/modifier|update/i.test(actionLabel)?'Modification…':'Enregistrement…';submitControl.insertAdjacentHTML('afterbegin','<span class="admin-button-spinner" aria-hidden="true"></span> ')} });
   dialog.querySelector('.modal-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>{trigger.focus({preventScroll:true})});index++;
 });
})();
</script></body></html>